package com.projectmonitor.controller;
import com.projectmonitor.entity.*; import com.projectmonitor.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final ProjectRepository p;private final TaskRepository t;public DashboardController(ProjectRepository p,TaskRepository t){this.p=p;this.t=t;}@GetMapping public Map<String,Object> stats(){Map<String,Object>m=new LinkedHashMap<>();m.put("totalProjects",p.count());m.put("completedProjects",p.countByStatus(ProjectStatus.COMPLETED));m.put("inProgressProjects",p.countByStatus(ProjectStatus.IN_PROGRESS));m.put("onHoldProjects",p.countByStatus(ProjectStatus.ON_HOLD));m.put("totalTasks",t.count());m.put("completedTasks",t.countByStatus(TaskStatus.COMPLETED));m.put("pendingTasks",t.countByStatus(TaskStatus.PENDING));m.put("inProgressTasks",t.countByStatus(TaskStatus.IN_PROGRESS));return m;}}
